Here is the commit message:
f2fs: protect extension_list reading with sb_lock in
 f2fs_sbi_show()

In f2fs_sbi_show(), the extension_list, extension_count and
hot_ext_count are read without holding sbi->sb_lock. If a concurrent
sysfs store modifies the extension list via f2fs_update_extension_list(),
the show path may read inconsistent count and array contents, potentially
leading to out-of-bounds access or displaying stale data.

Fix this by holding sb_lock around the entire extension list read
and format operation.

Fixes: b6a06cbbb5f7 ("f2fs: support hot file extension")
Signed-off-by: Yongpeng Yang <yangyongpeng@xiaomi.com>
Reviewed-by: Chao Yu <chao@kernel.org>
Signed-off-by: Jaegeuk Kim <jaegeuk@kernel.org>

Here is the root cause:
In `f2fs_sbi_show()`, the `extension_list`, `extension_count`, and `hot_ext_count` fields are read without holding `sbi->sb_lock`, while a concurrent `f2fs_update_extension_list()` sysfs store modifies these same fields under `sb_lock`. This race condition can cause the show path to read an `extension_count` or `hot_ext_count` that is inconsistent with the actual content of `extension_list`, leading to potential out-of-bounds array access or displaying stale data.

Here is the patch:

 static ssize_t f2fs_sbi_show(struct f2fs_attr *a,
 			struct f2fs_sb_info *sbi, char *buf)
 {
 	unsigned char *ptr = NULL;

 	ptr = __struct_ptr(sbi, a->struct_type);
 	if (!ptr)
 		return -EINVAL;

 	if (!strcmp(a->attr.name, "extension_list")) {
 		__u8 (*extlist)[F2FS_EXTENSION_LEN] =
 					sbi->raw_super->extension_list;
-		int cold_count = le32_to_cpu(sbi->raw_super->extension_count);
-		int hot_count = sbi->raw_super->hot_ext_count;
+		int cold_count, hot_count;
 		int len = 0, i;

+		f2fs_down_read(&sbi->sb_lock);
+		cold_count = le32_to_cpu(sbi->raw_super->extension_count);
+		hot_count = sbi->raw_super->hot_ext_count;
 		len += sysfs_emit_at(buf, len, "cold file extension:\n");
 		for (i = 0; i < cold_count; i++)
 			len += sysfs_emit_at(buf, len, "%s\n", extlist[i]);

 		len += sysfs_emit_at(buf, len, "hot file extension:\n");
 		for (i = cold_count; i < cold_count + hot_count; i++)
 			len += sysfs_emit_at(buf, len, "%s\n", extlist[i]);
+		f2fs_up_read(&sbi->sb_lock);

 		return len;
 	}

 	if (!strcmp(a->attr.name, "ckpt_thread_ioprio")) {
 		struct ckpt_req_control *cprc = &sbi->cprc_info;
 		int class = IOPRIO_PRIO_CLASS(cprc->ckpt_thread_ioprio);
 		int level = IOPRIO_PRIO_LEVEL(cprc->ckpt_thread_ioprio);

 		if (class != IOPRIO_CLASS_RT && class != IOPRIO_CLASS_BE)
 			return -EINVAL;

 		return sysfs_emit(buf, "%s,%d\n",
 			class == IOPRIO_CLASS_RT ? "rt" : "be", level);
 	}

 #ifdef CONFIG_F2FS_FS_COMPRESSION
 	if (!strcmp(a->attr.name, "compr_written_block"))
 		return sysfs_emit(buf, "%llu\n", sbi->compr_written_block);

 	if (!strcmp(a->attr.name, "compr_saved_block"))
 		return sysfs_emit(buf, "%llu\n", sbi->compr_saved_block);

 	if (!strcmp(a->attr.name, "compr_new_inode"))
 		return sysfs_emit(buf, "%u\n", sbi->compr_new_inode);
 #endif

 	if (!strcmp(a->attr.name, "gc_segment_mode"))
 		return sysfs_emit(buf, "%u\n", sbi->gc_segment_mode);

 	if (!strcmp(a->attr.name, "gc_reclaimed_segments")) {
 		return sysfs_emit(buf, "%u\n",
 			sbi->gc_reclaimed_segs[sbi->gc_segment_mode]);
 	}

 	if (!strcmp(a->attr.name, "current_atomic_write")) {
 		s64 current_write = atomic64_read(&sbi->current_atomic_write);

 		return sysfs_emit(buf, "%lld\n", current_write);
 	}

 	if (!strcmp(a->attr.name, "peak_atomic_write"))
 		return sysfs_emit(buf, "%lld\n", sbi->peak_atomic_write);

 	if (!strcmp(a->attr.name, "committed_atomic_block"))
 		return sysfs_emit(buf, "%llu\n", sbi->committed_atomic_block);

 	if (!strcmp(a->attr.name, "revoked_atomic_block"))
 		return sysfs_emit(buf, "%llu\n", sbi->revoked_atomic_block);

 #ifdef CONFIG_F2FS_STAT_FS
 	if (!strcmp(a->attr.name, "cp_foreground_calls"))
 		return sysfs_emit(buf, "%d\n",
 				atomic_read(&sbi->cp_call_count[TOTAL_CALL]) -
 				atomic_read(&sbi->cp_call_count[BACKGROUND]));
 	if (!strcmp(a->attr.name, "cp_background_calls"))
 		return sysfs_emit(buf, "%d\n",
 				atomic_read(&sbi->cp_call_count[BACKGROUND]));
 #endif

 	return __sbi_show_value(a, sbi, buf, ptr + a->offset);
 }



